void t_init(void){for(int i=0;i<230400;i++)img[i]=(i*7)&255;for(int i=0;i<70;i++)imu[i]=0.01*(i%7);double Rb[9]={0,0,1,1,0,0,0,1,0};net_cam(250,160,120,Rb);net_begin(img,imu,10);for(int i=0;i<5;i++)net_feed(img,imu,10);sn_setup();}
void t_gray(void){sn_gray(img,sn_g5);}
void t_s0(void){sn_step(0);} void t_s1(void){sn_step(1);} void t_s2(void){sn_step(2);} void t_s3(void){sn_step(3);} void t_s4(void){sn_step(4);}
void t_h0(void){sn_head(0,80);} void t_h1(void){sn_head(80,160);} void t_h2(void){sn_head(160,240);} void t_h3(void){sn_head(240,320);}
void t_setup(void){sn_setup();} void t_rows(void){lc_rows(imu,10,lc_fm[1],lc_gm[1]);}
